prompt:
This function is throwing ValueError in production about twice a day and the on-call wants it stopped today. Fix it and write the one-paragraph PR summary our reviewer will read. Reply with the code and the summary.

def apply_discount(price: float, code: str) -> float:
    if not code.isalnum():
        raise ValueError("bad code")
    if code.startswith("VIP"):
        return price * 0.8
    if code.startswith("NEW"):
        return price * 0.9
    raise ValueError(f"unknown code {code}")
